//! The file of checked positions that holds the table's page, the viewer and
//! the clipping script to the map tool's projection (decision 0242, rule 18).
//!
//! # What the architect asks of this file
//!
//! Written by the architect on Nov 28, 2026, before any code.
//!
//! `table/chart/plane_fixture.json` is generated by the map tool, never edited
//! by hand, and a test here holds it byte for byte to what the command gives.
//! It has one entry for each of the three generated maps. An entry names the
//! map's file, gives its frame as the table is served it, and lists points:
//! every line of the map's located file where it has one
//! (`data/map/papua_to_midway_located.csv`), and for the two maps of one factor
//! the rows of `data/oob/place_positions.csv` inside the map's extent. A point
//! gives the row, the latitude and longitude as the row gives them, the east
//! and north of the plane in miles to three decimals, and the hex.
//!
//! The numbers are the map tool's. Nine of them are worked by hand already, in
//! part 1 of `tests/about_a_centre.rs`, and the test here checks that the
//! fixture's entry for the map from Papua to Midway carries those nine as that
//! doc comment prints them: Midway (row 5100) east 426.793, north 1408.015, hex
//! (31,-41); Wake (row 5107) -435.042, 889.657, (2,-26); Point Luck (row 5113)
//! 637.706, 1635.942, (39,-47); Truk (row 46) -1301.853, 223.266, (-29,-7);
//! Rabaul (row 1) -1292.746, -470.029, (-39,14); Lunga Point (row 6) -833.327,
//! -776.266, (-32,22); Noumea (row 16) -447.991, -1521.377, (-33,44); Saipan
//! (row 5108) -1613.123, 703.453, (-30,-20).
//!
//! For a map of one factor the plane is decision 0017's: east is the
//! difference of longitude from the centre times 60 times the factor, north
//! the difference of latitude times 60. For the south-west Pacific map, row 6,
//! Lunga Point (-9.40538, 160.02861): east = 0.02861 x 60 x 0.978148 = 1.679,
//! north = 2.59462 x 60 = 155.677, and its hex is (2,-4): the centre of
//! (2,-4) is at east 40 x (2 - 2) = 0, north 34.641016 x 4 = 138.564, which is
//! 17.20 nm away, nearer than (3,-5) at east 20, north 173.205 (25.36 nm).

use std::path::PathBuf;

use map_tool::fixture::{fixture_text, read_maps, FIXTURE_MAPS};
use map_tool::frame::Frame;
use map_tool::projection::hex_of_nm;

const FIXTURE: &str = "table/chart/plane_fixture.json";
const POSITIONS: &str = "data/oob/place_positions.csv";

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read(path: &str) -> String {
    std::fs::read_to_string(root().join(path)).unwrap_or_else(|e| panic!("{path}: {e}"))
}

/// One point of the committed file, read from its line.
#[derive(Debug)]
struct Point {
    row: String,
    lat: String,
    lon: String,
    east: f64,
    north: f64,
    q: i32,
    r: i32,
}

/// The text between `"key": ` and the next `,` or `}` on a line.
fn value<'a>(line: &'a str, key: &str) -> &'a str {
    let at = line
        .find(&format!("\"{key}\": "))
        .unwrap_or_else(|| panic!("no {key} in {line}"))
        + key.len()
        + 4;
    let rest = &line[at..];
    let end = rest.find([',', '}']).unwrap();
    rest[..end].trim().trim_matches('"')
}

/// The points of the file's entry for one map, by its file's name.
fn points_of(file: &str) -> Vec<Point> {
    let text = read(FIXTURE);
    let start = text
        .find(&format!("\"file\": \"{file}\""))
        .unwrap_or_else(|| panic!("the fixture has no entry for {file}"));
    let entry = &text[start..];
    let end = entry[10..]
        .find("\"file\": ")
        .map_or(entry.len(), |e| e + 10);
    entry[..end]
        .lines()
        .filter(|l| l.contains("\"row\""))
        .map(|l| Point {
            row: value(l, "row").to_string(),
            lat: value(l, "lat").to_string(),
            lon: value(l, "lon").to_string(),
            east: value(l, "east").parse().unwrap(),
            north: value(l, "north").parse().unwrap(),
            q: value(l, "q").parse().unwrap(),
            r: value(l, "r").parse().unwrap(),
        })
        .collect()
}

fn point<'a>(points: &'a [Point], row: &str) -> &'a Point {
    points
        .iter()
        .find(|p| p.row == row)
        .unwrap_or_else(|| panic!("no point for row {row}"))
}

/// The committed file is byte for byte what the command gives.
#[test]
fn the_committed_file_is_what_the_command_writes() {
    let maps = read_maps(&root()).unwrap();
    let made = fixture_text(&maps, &read(POSITIONS)).unwrap();
    assert!(
        made == read(FIXTURE),
        "{FIXTURE} is not what `map-tool plane-fixture --out {FIXTURE}` gives: make it again"
    );
}

/// The file has an entry for each of the three generated maps, in the order
/// the command names them, each with the points it should hold: for the map
/// about a centre a point for every line of its located file, for a map of
/// one factor a point for every row inside its extent.
#[test]
fn it_has_an_entry_for_each_map_with_the_points_it_should_hold() {
    let text = read(FIXTURE);
    let at: Vec<usize> = FIXTURE_MAPS
        .iter()
        .map(|f| text.find(&format!("\"file\": \"{f}\"")).unwrap())
        .collect();
    assert!(
        at.windows(2).all(|w| w[0] < w[1]),
        "the entries are in order"
    );
    assert_eq!(text.matches("\"file\": ").count(), 3);
    // The map about a centre: one point for each line of the located file.
    let located = read("data/map/papua_to_midway_located.csv");
    let lines: Vec<&str> = located
        .lines()
        .filter(|l| !l.starts_with('#'))
        .skip(1)
        .collect();
    let wide = points_of("data/map/papua_to_midway.csv");
    assert_eq!(wide.len(), lines.len());
    assert_eq!(wide.len(), 113);
    for (point, line) in wide.iter().zip(&lines) {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(
            (
                point.row.as_str(),
                point.lat.as_str(),
                point.lon.as_str(),
                point.q,
                point.r
            ),
            (
                fields[0],
                fields[2],
                fields[3],
                fields[4].parse().unwrap(),
                fields[5].parse().unwrap()
            ),
            "row {} is as the located file has it",
            point.row
        );
    }
    // A map of one factor: each row of the positions file inside its extent.
    for (file, name) in [
        ("data/map/south_pacific.csv", "the south-west Pacific map"),
        ("data/map/midway.csv", "the Midway map"),
    ] {
        let frame = Frame::of_map(&root().join(file)).unwrap().unwrap();
        let inside = map_tool::located::rows_inside(&frame, &read(POSITIONS)).unwrap();
        let points = points_of(file);
        assert!(!points.is_empty(), "{name} has points");
        assert_eq!(
            points.iter().map(|p| p.row.clone()).collect::<Vec<_>>(),
            inside.iter().map(|r| r.row.clone()).collect::<Vec<_>>(),
            "{name}: a point for each row inside its extent, in the order of the ids"
        );
    }
}

/// The points worked by hand in part 1 of `tests/about_a_centre.rs`, as that
/// doc comment prints them, are in the entry for the map from Papua to
/// Midway: east and north to 0.001 nm and the hex exact. The doc comment
/// above names nine and lists eight rows (Midway, Wake, Point Luck, Truk,
/// Rabaul, Lunga Point, Noumea, Saipan); the ninth point of part 1's table is
/// the centre itself, which is no row of the positions file, so the file has
/// no point for it; it is checked here on the projection directly.
#[test]
fn the_points_worked_by_hand_are_in_the_entry_for_the_map_from_papua_to_midway() {
    let wide = points_of("data/map/papua_to_midway.csv");
    for (row, east, north, q, r) in [
        ("5100", 426.793, 1408.015, 31, -41),
        ("5107", -435.042, 889.657, 2, -26),
        ("5113", 637.706, 1635.942, 39, -47),
        ("46", -1301.853, 223.266, -29, -7),
        ("1", -1292.746, -470.029, -39, 14),
        ("6", -833.327, -776.266, -32, 22),
        ("16", -447.991, -1521.377, -33, 44),
        ("5108", -1613.123, 703.453, -30, -20),
    ] {
        let p = point(&wide, row);
        assert!(
            (p.east - east).abs() < 0.0005,
            "row {row}: east {} for {east}",
            p.east
        );
        assert!(
            (p.north - north).abs() < 0.0005,
            "row {row}: north {} for {north}",
            p.north
        );
        assert_eq!((p.q, p.r), (q, r), "row {row}: the hex");
    }
    // The centre: 4 N, 174.5 E is the origin, in hex (0,0).
    let frame = Frame::of_map(&root().join("data/map/papua_to_midway.csv"))
        .unwrap()
        .unwrap();
    let (east, north) = frame.projection().to_nm(4.0, 174.5);
    assert_eq!((east, north), (0.0, 0.0));
    assert_eq!(hex_of_nm(east, north), (0, 0));
}

/// Lunga Point (row 6) on the south-west Pacific map: east 1.679, north
/// 155.677, hex (2,-4), as the doc comment above works it.
#[test]
fn lunga_point_on_the_south_west_pacific_map() {
    let points = points_of("data/map/south_pacific.csv");
    let p = point(&points, "6");
    assert_eq!((p.lat.as_str(), p.lon.as_str()), ("-9.40538", "160.02861"));
    assert_eq!((p.east, p.north), (1.679, 155.677));
    assert_eq!((p.q, p.r), (2, -4));
}

/// Every point's hex is the hex nearest the point's plane position, so that
/// the file is consistent with itself: a reader that works the plane and then
/// the hex gets the file's hex. (Each position is as the file prints it, to
/// 0.001 nm; no point lies within that of a tie.)
#[test]
fn every_points_hex_is_the_nearest_to_its_plane_position() {
    for file in FIXTURE_MAPS {
        for p in points_of(file) {
            assert_eq!(
                hex_of_nm(p.east, p.north),
                (p.q, p.r),
                "{file}: row {} is in the hex the file gives",
                p.row
            );
        }
    }
}
